import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class QualitySpeedDemo {

    private static final Logger log = Logger.getLogger(QualitySpeedDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Risk-based quality vs speed decision at " + BANK_NAME);

        QualityGate gate = new QualityGate();
        List<Component> components = new ArrayList<>();
        components.add(new Component("Balance calculation (SAV2001/CUR3001)", "HIGH"));
        components.add(new Component("Transfer list", "HIGH"));
        components.add(new Component("Cosmetic spending chart", "LOW"));

        for (Component c : components) {
            gate.decide(c);
        }

        log.info(() -> "Deferred quality debt tracked: " + gate.getDeferredDebt());
    }
}

// ─── Would be in model/Component.java in a real project ───
class Component {
    private final String name;
    private final String riskLevel; // HIGH or LOW

    Component(String name, String riskLevel) {
        this.name = name;
        this.riskLevel = riskLevel;
    }

    String getName() { return name; }
    String getRiskLevel() { return riskLevel; }
    boolean isHighRisk() { return "HIGH".equals(riskLevel); }
}

// ─── Would be in gate/QualityGate.java in a real project ───
class QualityGate {
    private static final Logger log = Logger.getLogger(QualityGate.class.getName());
    private final List<String> deferredDebt = new ArrayList<>();

    void decide(Component c) {
        if (c.isHighRisk()) {
            log.info(() -> "FULL QUALITY for '" + c.getName()
                    + "' — money/correctness path. Full tests + review required before launch.");
        } else {
            log.warning(() -> "SHIP FAST for '" + c.getName()
                    + "' — low risk. Lighter bar now, improve later.");
            deferredDebt.add(c.getName() + " — add polish + tests post-launch");
        }
    }

    List<String> getDeferredDebt() {
        return deferredDebt;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
